namespace ZteImeiStudio.Windows;

internal sealed record OperationHelpSection(string Title, string Body, string? Commands = null);
internal sealed record OperationHelpTopic(string Title, string AccessibleName, string Introduction,
    IReadOnlyList<OperationHelpSection> Sections);

/// <summary>
/// User-facing account of the implemented Windows workflows. Keep this aligned
/// with Core/OnboardingEngine.cs, Core/ImeiEngine*.cs and the pinned device payloads.
/// </summary>
internal static class OperationHelpContent
{
    public static OperationHelpTopic FirmwareAdaptation { get; } = new(
        "Сбор данных для адаптации прошивки", "Что входит в данные для адаптации прошивки",
        "Сведения об устройстве, файлы прошивки и результаты чтения DIAG/QMI для исследования IMEI и SIM/eSIM — в одном ZIP. Подробные проверки остаются в архиве.",
        [
            new("Что сохраняется", "Свежий технический отчёт по функциям программы, структура API, сведения о службах и ядре, исходные файлы экрана, сетевых и модемных компонентов, библиотеки DIAG/QMI/RIL, языки и шрифты. В архив входят версии и контрольные суммы файлов, состояние компонентов и очищенный журнал программы. Отсутствующие файлы и неудачные запросы перечислены отдельно."),
            new("Исследование IMEI и eSIM", "Через SSH временно запускаются помощники чтения: ответы NV550, структура EFS config и состояние карт и слотов через QMI. Сохраняются коды ответов, размеры и результаты проверок, без IMEI, ICCID, EID и содержимого NV/config. Для съёмной eUICC и встроенной eSIM соберите отдельные ZIP, предварительно выбрав нужную SIM штатным способом и дождавшись её готовности. Программа сама не переключает SIM; номера слотов сохраняются без догадок об их назначении. Эти данные нужны для адаптации и не подтверждают возможность записи IMEI или установки eSIM."),
            new("Что не меняется", "Сбор не записывает NV/config, не меняет IMEI, не перезапускает радио, не переключает слот и не выполняет APDU-команды или операции с профилями eSIM. Службы не перезапускаются. Временные помощники удаляются после чтения. Пароли, ключи, профили, настройки пользователя и полный образ флеш-памяти в архив не включаются."),
            new("Как используется архив", "ZIP сохраняется только в выбранный вами файл и автоматически никуда не отправляется. Файлы прошивки передавайте лично для исследования, а не публикуйте как часть приложения. Недоступность отдельного диагностического запроса отмечается в архиве; успешное чтение само по себе не разрешает запись на неподдерживаемую прошивку.")
        ]);
    public static OperationHelpTopic DiagnosticAdb { get; } = new(
        "ADB для диагностики", "Подробно о включении диагностического ADB", "Первоначальное включение ADB выполняется флажком в настройках подключения. При работающем SSH используется отдельное проверенное управление состоянием ADB; этот путь не устанавливает агент или SSH.",
        [
            new("1. Проверка доступа и модема",
                "Проверяются незавершённые операции и идентичность. Уже работающий root USB ADB подтверждается повторно и сохраняется без переключения USB, бэкапа или перезагрузки. Обычные операции программы продолжают работать по SSH."),
            new("2. Последовательное включение",
                "Известный ключ формата используется как кандидат при пустом Backup-key suffix. Ручное значение используется без резервной попытки; неверный ключ останавливает обработку архива. Пароли и suffix остаются только в памяти для текущего модема между действиями и вкладками; при смене модема или закрытии программы они очищаются. В журнал они не записываются. Совпадение ключа само по себе не разрешает восстановление: проверяются архив, MD5, шаблон rc.local, USB-путь и неизменность остальных файлов. Сначала отправляется одна известная команда zwrt_bsp.usb.set mode=debug, если список методов подтверждает её или недоступен; при явном отсутствии команда пропускается. Только если root ADB не появился, сохраняется свежий зашифрованный бэкап и проверяется поддерживаемый шаблон. Название прошивки не заменяет проверку фактических данных. Восстановление отправляется один раз. Если точная строка включения уже есть, возможна одна штатная перезагрузка без восстановления."),
            new("3. Отключение ADB после подготовки",
                "После успешной проверки SSH программа отключает ADB и удаляет добавленную при подготовке строку его автозапуска. Кнопка «Выключить ADB и автозапуск» делает это отдельно. Сначала сохраняется копия rc.local. USB-соединение может кратко переподключиться; результат подтверждается через SSH. Если SSH не вернётся, исходные USB-функции и автозапуск восстанавливаются."),
            new("4. Продолжение после обрыва",
                "Намерение сохраняется до запроса. Повторный запуск проверяет результат на том же модеме; уже отправленные USB debug, восстановление и перезагрузка не повторяются. Неизвестный результат сохраняет журнал для продолжения. Проверки CID, boot ID, root и соответствия устройства остаются обязательными для установки.")
        ]);

    public static OperationHelpTopic Preparation { get; } = new(
        "Как выполняется предварительная подготовка", "Подробно о предварительной подготовке модема", "Подготовка проверяет существующий SSH, затем root USB ADB. Если доступа нет, используются известная штатная USB-команда и, при необходимости, восстановление строго проверенного шаблона бэкапа. Открытие справки ничего не запускает.",
        [
            new("Проверка ключа без подготовки доступа",
                "Кнопка «Проверить ключ бэкапа» использует только пароль Web и необязательный ручной suffix. Она сохраняет свежий зашифрованный оригинал и идентичность локально, проверяет расшифровку, MD5 и структуру архива в памяти. Известный ключ формата проверяется как кандидат независимо от имени прошивки. Совпадение ключа и формата не разрешает восстановление, ADB, SSH или установку компонентов; для этих действий сохраняются отдельные проверки. Неверный ручной suffix не подменяется автоматическим. Расшифрованные файлы на диск не записываются."),
            new("1. Проверка доступа и модема",
                "Подготовка автоматически заменяет агент, SSH и веб-панель текущими файлами приложения. Прежние основные файлы и журналы сохраняются в приватной копии. При подготовке применяется введённый пароль агента; кнопка установки встроенного агента сохраняет прежний пароль на модеме. Если прежний пароль нельзя безопасно сохранить, введите новый пароль в форме подготовки.\n\nНастройки VPN, профили, экранные страницы и остальные пользовательские данные сохраняются. Ключи SSH сохраняются; действующее соединение SSH не останавливается. Дополнительные режимы замены выбирать не требуется.\n\nЕсли SSH нет, используется проверенный root USB ADB. При наличии Web-входа USB должен совпасть с прочитанной идентичностью."),
            new("2. Если доступа ещё нет",
                "Известный ключ формата используется как кандидат при пустом Backup-key suffix. Ручное значение используется без резервной попытки; неверный ключ останавливает обработку архива. Пароли и suffix остаются только в памяти для текущего модема между действиями и вкладками; при смене модема или закрытии программы они очищаются. В журнал они не записываются. Совпадение ключа само по себе не разрешает восстановление: проверяются архив, MD5, шаблон rc.local, USB-путь и неизменность остальных файлов. Порядок: штатный USB debug — затем проверенный бэкап. При недоступной интроспекции проверяется только одна известная команда, без подбора имён или паролей. Явно отсутствующий метод пропускается. До восстановления сохраняется зашифрованный оригинал и сверяется идентичность. Неизвестный шаблон отказывается до загрузки на модем."),
            new("3. Установка SSH и агента",
                "После появления доступа проверяются фактические root, Linux ARM64, CID, boot ID, файловая система, инструменты и механизм запуска. Профиль linux-arm64-access устанавливает агент для информации и управления. Каждая операция проверяет необходимые ей компоненты; исследование прошивки выполняет программа по SSH. Хэши встроенных файлов, повторная идентификация, резервные копии и удалённые транзакции остаются обязательными."),
            new("4. Продолжение после обрыва",
                "Намерение сохраняется до изменения модема. Повторное нажатие сверяет устройство и журнал; подтверждённая замена основных файлов не повторяется из-за ошибки веб-панели. Старые журналы и копии сохраняются. Уже отправленная очистка продолжается по своему журналу; неотправленное намерение очистки снимается перед обычной заменой с сохранением настроек. Пароли и Web-сессия в журнал не записываются.")
        ]);

    public static OperationHelpTopic Imei { get; } = new(
        "Как записываются IMEI", "Подробно о записи IMEI",
        "Программа работает с одной или двумя активными записями NV550. Перед записью сохраняет проверенную копию, временно включает разрешение через EFS config и сверяет результат после перезагрузки. Неактивная NV1 не создаётся.",
        [
            new("1. Определение активных IMEI", "По SSH проверяются устройство, прошивка и diag-router. NV0 должен читаться и полностью совпадать с legacy NV550. NV1 либо читается, либо возвращает точный статус NV_NOTACTIVE_S (5). Ошибки транспорта и другие статусы останавливают операцию. API проверяется только для активных записей.", "<zte_nv> --snapshot-available"),
            new("2. Проверенная копия перед записью", "Сохраняются полные 128 байт каждой активной записи, EFS config и манифест с контрольными суммами. Для одного IMEI используются nv0.bin и config.bin; старые парные копии сохраняют совместимость. Число записей копии должно совпадать с текущим модемом. В каждом NV изменяются только первые 9 байт IMEI, остальные 119 байт сохраняются.", "<zte_config_read> --read-config"),
            new("3. Запись и проверка", "После проверки копии временно включается config102 и выполняется перезагрузка. План содержит исходные и целевые записи: 256 байт для одного IMEI, 512 для двух. После каждого шага проверяются все активные записи, их число и legacy-алиас. Затем возвращается исходный config и выполняется заключительная перезагрузка с проверкой NV и API. На B04 режим EFS config 0644 сохраняется при замене и откате.", "<zte_nv> --apply-plan <план>"),
            new("4. Ошибка или восстановление", "При обрыве сохраняются журнал и копия. Продолжение сверяет устройство, число записей и полные исходные либо целевые данные. Неизвестные данные не перезаписываются. Восстановление выбранной копии сначала сохраняет текущее состояние. Допуск определяется фактическими форматами NV/EFS и ABI diag-router. Аппаратная запись проверена на B31; запись на реальных B28 и B04 в этом цикле ещё не подтверждена.")
        ]);
}
